// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address target, uint128 _value) public {
        vm.assume(target != address(0));
        vm.assume(target != address(c));
        vm.assume(_value > 0);
        vm.deal(address(c), _value);
        uint balBefore = target.balance;
        c.sendMoney(target, _value);
        assertTrue(target.balance == balBefore + _value);
    }
}
